using NUnit.Framework;

[TestFixture]
public class FirstRepeatedLetterTests
{
    [Test]
    public void Returns_First_Repeated_Letter()
    {
        var result = FirstRepeatedLetter("Programming");
        Assert.That(result, Is.EqualTo('r'));
    }

    private char? FirstRepeatedLetter(string word)
    {
        var seen = new HashSet<char>();

        foreach (var ch in word.ToLowerInvariant())
        {
            if (!char.IsLetter(ch))
                continue;

            if (!seen.Add(ch))
                return ch;
        }

        return null;
    }
}
